    bowtie stimulus "A 68-year-old post-operative patient has a temperature of 38.9°C, heart rate 118/min, blood pressure 88/52 mm Hg, and rising lactate. Select the two priority actions, the condition the patient is most likely experiencing, and the two parameters to monitor."
      column-titles [
        "Actions to Take"
        "Condition Most Likely"
        "Parameters to Monitor"
      ] possible-responses [
      [
        "obtain blood cultures"
        "administer the prescribed fluid bolus"
        "encourage ambulation"
        "administer a sedative"
      ]
      [
        "sepsis"
        "pulmonary embolism"
        "acute myocardial infarction"
      ]
      [
        "serum lactate"
        "mean arterial pressure"
        "bowel sounds"
        "visual acuity"
      ]
    ] valid-response [
      [
        "obtain blood cultures"
        "administer the prescribed fluid bolus"
      ]
      [
        "sepsis"
      ]
      [
        "serum lactate"
        "mean arterial pressure"
      ]
    ] {}
  ] {}
] {}..

