set-var "lrn-id" get-val-public "itemId"
learnosity items [
  item metadata [
    tags {
      "Common Core": "HS-LS1-7"
      DOK: 2
      Difficulty: "medium"
    }
  ] questions [
    mcq stimulus "Which organelle is the site of aerobic respiration?"
      options [
        "Mitochondrion"
        "Ribosome"
        "Golgi apparatus"
        "Nucleus"
      ] valid-response [
      0
    ] metadata [
      distractor-rationale [
        "Correct — the mitochondrion is the site of aerobic respiration."
        "Confuses the mitochondrion with the ribosome, which synthesizes proteins, not ATP via respiration."
        "Confuses the mitochondrion with the Golgi apparatus, which packages and ships proteins rather than generating energy."
        "Confuses the mitochondrion with the nucleus, which stores genetic material rather than performing respiration."
      ]
    ] {}
  ] {}
] {}..

